def Lip (G : Gauge X I bot) (φ : Operator X bot)
    (L : ChannelMatrix I) : Prop :=
  LipOn G φ (dom φ) L

def lipMatricesOn (G : Gauge X I bot) (φ : Operator X bot)
    (U : Set X) : Set (ChannelMatrix I) :=
  {L | LipOn G φ U L}

def lipMatrices (G : Gauge X I bot) (φ : Operator X bot) :
    Set (ChannelMatrix I) :=
  {L | Lip G φ L}

def coLipMatricesOn (G : Gauge X I bot) (φ : Operator X bot)
    (U : Set X) : Set (ChannelMatrix I) :=
  {K | CoLipOn G φ U K}

def channelCoefficient {I : Type}
    (M : ChannelMatrix I) (c : ComponentChannel I) : ENNReal :=
  entry M c.1 c.2

theorem inputDomain_nonempty (φ : ℕ → Operator X bot) {U : Set X}
    (hne : U.Nonempty) (m : ℕ) : (inputDomain φ U m).Nonempty :=
  hne.image _

def Lip (d : I → X → X → ENNReal) (φ : Operator X bot) (U : Set X) : Set (Mat I) :=
  {L | U ⊆ dom φ ∧ ∀ x ∈ U, ∀ y ∈ U, ∀ j,
    d j (φ.func x) (φ.func y) ≤ act L (fun i => d i x y) j}

def CoLip (d : I → X → X → ENNReal) (φ : Operator X bot) (U : Set X) : Set (Mat I) :=
  {K | U.Nonempty ∧ U ⊆ dom φ ∧ ∀ x ∈ U, ∀ y ∈ U, ∀ j,
    act K (fun i => d i x y) j ≤ d j (φ.func x) (φ.func y)}

def Col (L : Mat I) (i j : I) : Prop := ∀ k, k ≠ j → L i k = 0
def Diagonal (L : Mat I) : Prop := ∀ i j, i ≠ j → L i j = 0
def RowDecoupled (d : I → X → X → ENNReal) (φ : Operator X bot) (U : Set X) (j : I) :
    Prop := ∃ L ∈ Lip d φ U, ∃ i, Row L i j
def ColDecoupled (d : I → X → X → ENNReal) (φ : Operator X bot) (U : Set X) (i : I) :
    Prop := ∃ L ∈ Lip d φ U, ∃ j, Col L i j

def Diagonal (L : Mat I) : Prop := ∀ i j, i ≠ j → L i j = 0
def RowDecoupled (d : I → X → X → ENNReal) (φ : Operator X bot) (U : Set X) (j : I) :
