def ScalarSet (d : I → X → X → ENNReal) (φ : Operator X bot)
    (U : Set X) (i j : I) : Set ENNReal :=
  {a | ∀ x ∈ U, ∀ y ∈ U, d j (φ.func x) (φ.func y) ≤ a * d i x y}
